async function api(path,body){let opts={cache:'no-store'};if(body!==undefined)opts={...opts,method:'POST',headers:{'Content-Type':'application/json','X-Analytics-UI':'1'},body:JSON.stringify(body)};let res=await fetch(new URL('api/'+path,document.baseURI),opts),data=await res.json();if(!res.ok)throw new Error(data.detail||res.statusText);return data}
function msg(text,error=false){clearTimeout(timer);$('notice').textContent=text;$('notice').className=error?'error':'';$('notice').hidden=false;timer=setTimeout(()=>$('notice').hidden=true,error?15000:6500)}
function fmt(v,d=2){return v==null?'—':Number(v).toLocaleString(cfg?.language==='en'?'en-GB':'nl-NL',{maximumFractionDigits:d,minimumFractionDigits:0})}
function localInput(d){const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,16)}
function query(){let w=$('window').value;if(w!=='custom')return '?hours='+w;return '?start='+encodeURIComponent($('start').value)+'&end='+encodeURIComponent($('end').value)}
function card(label,val,unit='',sub=''){return `<div class="metric"><div class="label">${esc(label)}</div><div class="value">${esc(val)}${val==='—'?'':` <small>${esc(unit)}</small>`}</div><div class="sub">${esc(sub)}</div></div>`}
function historyPeriod(s){return fmt(s.hours,3)+' '+tr('uur',Number(s.hours)===1?'hour':'hours')}
function historyCard(s,label,val,unit='',sub=''){return card(label,val,unit,sub).replace(/<\/div>$/, '<div class="period"><strong>'+esc(tr('Analyseperiode: ','Analysis period: ')+historyPeriod(s))+'</strong></div></div>')}
function renderComfort(s){
    let cov=tr('Gezamenlijke datadekking: ','Joint data coverage: ')+fmt(s.comfort_coverage_pct)+'%';
    let observed=tr('Geldige meettijd: ','Valid observation time: ')+fmt(s.comfort_observed_hours,3)+' '+tr('uur','h');
    let band=tr('Binnen ±0,5 °C van setpoint','Within ±0.5 °C of target');
    $('comfortTitle').textContent=tr('Thermisch comfort','Thermal comfort');
    $('comfortHint').textContent=tr('Alleen intervallen met zowel binnentemperatuur als setpoint tellen mee. Gemiddelde tekorten en percentages zijn gebaseerd op de geldige meettijd, inclusief momenten zonder tekort. De ±0,5 °C-band is een analytische referentie, geen bewezen comfortgrens.','Only intervals with both indoor temperature and target count. Average deficits and percentages use valid observation time, including periods without deficit. The ±0.5 °C band is an analytical reference, not a validated comfort threshold.');
    $('comfortCoverage').textContent=cov+' · '+observed;
    $('comfortValues').innerHTML=[
      historyCard(s,tr('Cumulatief comforttekort','Cumulative temperature deficit'),fmt(s.comfort_deficit_degree_hours),'°C·h',tr('Gemiddeld tekort: ','Mean deficit: ')+fmt(s.comfort_mean_deficit_c)+' °C'),
      historyCard(s,tr('Maximaal temperatuurtekort','Maximum temperature deficit'),fmt(s.comfort_max_deficit_c),'°C'),
      historyCard(s,band,fmt(s.comfort_within_band_pct),'%',tr('Onder band: ','Below band: ')+fmt(s.comfort_below_band_pct)+'% · '+tr('Boven band: ','Above band: ')+fmt(s.comfort_above_band_pct)+'%'),
      historyCard(s,tr('Gemiddelde binnentemperatuur','Average indoor temperature'),fmt(s.comfort_mean_inside_c),'°C'),
      historyCard(s,tr('Gemiddeld setpoint','Average target temperature'),fmt(s.comfort_mean_target_c),'°C'),
      historyCard(s,tr('Cumulatief temperatuuroverschot','Cumulative temperature excess'),fmt(s.comfort_excess_degree_hours),'°C·h',tr('Gemiddeld overschot: ','Mean excess: ')+fmt(s.comfort_mean_excess_c)+' °C')
    ].join('');
}
function renderFlow(s){let f=s.flow_comparison;$('flowCompare').hidden=!f;if(!f)return;$('flowCompareValues').innerHTML=[historyCard(s,'Primaire flow',fmt(f.primary_lh),'L/h'),historyCard(s,'Referentieflow',fmt(f.reference_lh),'L/h'),historyCard(s,'Verschil referentie − primair',fmt(f.bias_lh),'L/h'),historyCard(s,'Gemiddelde absolute afwijking',fmt(f.mae_lh),'L/h'),historyCard(s,'Relatieve afwijking',fmt(f.relative_bias_pct),'%'),historyCard(s,'Gezamenlijke dekking',fmt(f.coverage_pct),'%')].join('');$('flowBands').innerHTML=f.flow_bands.map(b=>`<tr><td>${b.min_lh}–${b.max_lh??'∞'}</td><td>${fmt(b.hours)}</td><td>${fmt(b.bias_lh)}</td><td>${fmt(b.relative_bias_pct)}</td></tr>`).join('');$('flowDefrost').textContent='Afwijking tijdens defrost: '+fmt(f.defrost.bias_lh)+' L/h · Buiten defrost: '+fmt(f.non_defrost.bias_lh)+' L/h';}
function renderSummary(){let s=summary;if(!s)return;renderFlow(s);renderComfort(s);$('historyRange').textContent=tr('Van ','From ')+s.start.replace('T',' ')+tr(' tot ',' to ')+s.end.replace('T',' ');let m=s.means||{};$('kpis').innerHTML=[historyCard(s,cfg.language==='en'?'Average net thermal power':'Gemiddeld netto thermisch vermogen',fmt(s.net_thermal_kw),'kW',(cfg.language==='en'?'Includes negative defrost heat · coverage ':'Inclusief negatieve defrostwarmte · dekking ')+fmt(s.thermal_coverage_pct,1)+'%'),historyCard(s,tr('Totale netto thermische energie','Total net thermal energy'),fmt(s.net_thermal_kwh),'kWh','Gemeten, incl. negatieve warmte'),historyCard(s,'Systeem-COP',fmt(s.system_cop),'','Dekking '+fmt(s.cop_coverage_pct,1)+'%'),historyCard(s,tr('Totaal elektrisch systeemverbruik','Total system electricity consumption'),fmt(s.system_electrical_kwh),'kWh','Inclusief BUH indien gemeten'),historyCard(s,tr('Gemiddelde compressorfrequentie','Average compressor frequency'),fmt(m.frequency,1),'Hz',fmt(s.compressor_high_pct_observed,1)+'% boven ingestelde drempel'),historyCard(s,tr('Totale defrostduur','Total defrost duration'),fmt(s.defrost_minutes,1),'min',fmt(s.defrost_starts,0)+' waargenomen starts · '+fmt(s.defrost_pct_observed,1)+'% van bekende tijd'),historyCard(s,'BUH-verbruik',fmt(s.buh_kwh),'kWh','Afzonderlijk indien gemeten'),historyCard(s,tr('Gemiddeld binnen / doel','Average indoor / target'),`${fmt(m.inside,1)} / ${fmt(m.target,1)}`,'°C'),historyCard(s,tr('Gemiddelde buitentemperatuur','Average outdoor temperature'),fmt(m.outside,1),'°C',s.weather_sources?.outside||''),historyCard(s,tr('Gemiddeld debiet','Average flow'),fmt(m.flow,0),'L/h'),historyCard(s,'Negatieve warmte tijdens defrost',fmt(s.defrost_negative_kwh),'kWh','Direct gemeten, excl. gemiste productie')].join('');$('warnings').innerHTML=s.warnings.map(v=>`<div>${esc(v)}</div>`).join('');$('cycles').innerHTML=s.cycles.length?[...s.cycles].sort((a,b)=>Date.parse(b.start)-Date.parse(a.start)).map(c=>`<tr><td>${esc(c.start.replace('T',' ').slice(0,16))}</td><td>${fmt(c.minutes,1)} min</td><td>${fmt(c.negative_heat_kwh,3)} kWh</td><td>${c.start_observed&&c.end_observed?'Ja':'Nee / grens'}</td></tr>`).join(''):'<tr><td colspan="4">Geen waargenomen perioden in de beschikbare data.</td></tr>';$('coverage').innerHTML=Object.entries(s.coverage_pct).map(([k,v])=>`<div class="barrow"><span>${esc(labels[k]||k)}</span><span class="bar"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></span><span>${fmt(v,1)}%</span></div>`).join('')||'Nog geen gekoppelde meetreeksen.';$('expertValues').innerHTML=Object.keys(labels).filter(k=>roles[k]?.mode==='expert'&&m[k]!=null).map(k=>historyCard(s,labels[k],fmt(k==='wet'?m[k]*100:m[k]),k==='wet'?'% nat':cfg.mapping[k]?.unit==='%'&&['fan','eev'].includes(k)?'%':roles[k].unit,s.weather_sources?.[k]||'')).join('')||'<p>Voeg expertmetingen toe in de configuratiewizard.</p>'}
// Colors are CSS tokens so existing SVGs respond to theme changes.
const chartRoles={heat:['heat','electric'],temp:['indoor','outdoor','heat','return'],freq:['electric','secondary'],flow:['return','secondary'],cop:['efficiency','secondary'],weather:['outdoor','return','heat']};
const chartDashes=['','7 4','2 4','10 3 2 3','4 3'];
const chartColor=role=>'var(--ohpa-chart-'+role+')';
function chart(){let rows=hourRows,kind=$('chartType').value,series;const colors=(chartRoles[kind]||chartRoles.weather).map(chartColor);if(kind==='heat')series=[['Netto thermisch kW',r=>r.net_thermal_kw],['Elektrisch systeem kW',r=>r.system_electrical_kwh==null?null:r.system_electrical_kwh/r.hours]];else if(kind==='temp')series=['inside','outside','supply','return'].map(k=>[labels[k],r=>r.means[k]]);else if(kind==='freq')series=[['Compressor Hz',r=>r.means.frequency],['Defrost % bekende tijd',r=>r.defrost_pct_observed]];else if(kind==='flow')series=[['Primair L/h',r=>r.flow_comparison?.primary_lh??null],['Referentie L/h',r=>r.flow_comparison?.reference_lh??null]];else if(kind==='cop')series=[['Systeem-COP',r=>r.system_cop],['Meetgrens-COP',r=>r.boundary_cop]];else series=[['Wind m/s',r=>r.means.wind],['Vocht %',r=>r.means.humidity],['Zon W/m²',r=>r.means.solar]];if(!rows.length){$('chart').textContent='Nog geen meetgegevens.';return}let w=1000,h=290,l=64,rgt=20,top=20,b=38;let xs=rows.map((x,i)=>l+i*(w-l-rgt)/Math.max(1,rows.length-1));let values=series.flatMap(([_,fn])=>rows.map(fn)).filter(v=>v!=null&&Number.isFinite(v));if(!values.length){$('chart').textContent='Geen geldige waarden voor deze grafiek.';$('legend').textContent='';return}let individual=kind==='weather';let min=Math.min(0,...values),max=Math.max(1,...values);if(kind==='temp'){min=Math.floor(Math.min(...values)/5)*5;max=Math.ceil(Math.max(...values)/5)*5;if(min===max)max+=5}let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Uurwaarden">`;for(let i=0;i<=4;i++){let y=top+i*(h-top-b)/4;svg+=`<line x1="${l}" y1="${y}" x2="${w-rgt}" y2="${y}" stroke="currentColor" opacity=".12"/><text x="${l-8}" y="${y+4}" text-anchor="end" font-size="12" fill="currentColor">${individual?fmt((4-i)*25,0)+'%':fmt(max-(max-min)*i/4,1)}</text>`}series.forEach(([name,fn],j)=>{let vv=rows.map(fn),scale=individual?Math.max(1,...vv.filter(x=>x!=null)):max,lo=individual?0:min;let parts=[],seg=[];vv.forEach((v,i)=>{if(v==null||!Number.isFinite(v)){if(seg.length)parts.push(seg);seg=[];return}let y=top+(scale-v)*(h-top-b)/Math.max(.001,scale-lo);seg.push([xs[i],y,v,i])});if(seg.length)parts.push(seg);parts.forEach(p=>{svg+=`<polyline fill="none" stroke="${colors[j]}" stroke-width="2.2" stroke-dasharray="${chartDashes[j]}" points="${p.map(x=>x.slice(0,2).join(',')).join(' ')}"/>`;p.forEach(([x,y,v,i])=>svg+=`<circle cx="${x}" cy="${y}" r="${rows.length>72?1.4:2.8}" fill="${colors[j]}"><title>${esc(name)} ${fmt(v)} · ${esc(rows[i].start)}</title></circle>`)})});let step=Math.max(1,Math.ceil(rows.length/7));for(let i=0;i<rows.length;i+=step)svg+=`<text x="${xs[i]}" y="${h-9}" text-anchor="${i===0?'start':'middle'}" font-size="11" fill="currentColor">${esc(rows[i].start.slice(5,16).replace('T',' '))}</text>`;$('chart').innerHTML=svg+'</svg>';$('legend').innerHTML=series.map(([name],i)=>`<span><i style="border-color:${colors[i]};border-top-style:${i===0?'solid':i===2?'dotted':'dashed'}"></i>${esc(name)}${individual?' (relatief eigen max.)':''}</span>`).join('')}
async function refresh(){try{$('refresh').disabled=true;summary=await api('metrics'+query());renderSummary();let period=new URLSearchParams({start:summary.start,end:summary.end});hourRows=await api('hourly?'+period);chart();await health()}catch(e){msg(e.message,true)}finally{$('refresh').disabled=false}}
async function health(){try{let s=await api('status');let errors=s.collector?.errors||[],mapped=Object.keys(s.series||{}).length;let pending=s.collector?.backfill_pending_series||0;$('health').textContent=!mapped?'Setup nodig':errors.length?'Collector: aandacht':pending?'Historie ophalen…':'Collector actief';$('health').className='pill'+(errors.length?' error':'');$('collection').innerHTML=`<p>Laatste poging: ${esc(s.collector?.last_attempt||'nog geen')}</p>${errors.map(e=>`<div>${esc(e)}</div>`).join('')}<div>${mapped} reeksen gekoppeld. ${pending} nog in backfill.</div>`}catch(e){$('health').textContent='Verbinding mislukt';$('health').className='pill error'}}
function normalize(u){let s=String(u||'').toLowerCase().replaceAll('³','3').replaceAll('²','2').replaceAll(' ','');return ({'l/hr':'l/h','l/hour':'l/h','lph':'l/h','lpm':'l/min'})[s]||s}
function mappingRow(k){let def=roles[k],m=cfg.mapping[k]||{},r=document.createElement('tr');r.dataset.role=k;r.innerHTML=`<td><span class="label">${esc(labels[k]||def.label)}${def.required?' *':''}</span><div class="hint">Doeleenheid: ${esc(def.unit)}</div>${k==='flow_counter'?'<div class="hint">Optioneel: alleen nodig zonder directe flowmeting.</div>':k==='illuminance'?'<div class="hint">Lokale lichtproxy, geen W/m².</div>':''}</td><td><input class="search" placeholder="Filter op naam of entity-ID"><select class="entity"><option value="">Niet gekoppeld</option></select><div class="live"></div></td><td><select class="attribute"><option value="">State</option></select>${def.unit==='on/off'?'<input class="onValue" placeholder="Actieve waarde (on)">':''}</td><td><select class="unit">${def.units.map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('')}</select></td>`;let sel=r.querySelector('.entity'),filter=r.querySelector('.search'),attr=r.querySelector('.attribute'),unit=r.querySelector('.unit'),on=r.querySelector('.onValue');function list(chosen){let term=filter.value.toLowerCase();let choices=entities.filter(e=>!term||(e.entity_id+' '+e.name).toLowerCase().includes(term)||e.entity_id===chosen);sel.innerHTML='<option value="">Niet gekoppeld</option>'+choices.map(e=>`<option value="${esc(e.entity_id)}">${esc(e.name)} — ${esc(e.entity_id)}</option>`).join('');if(chosen&&!choices.some(e=>e.entity_id===chosen))sel.insertAdjacentHTML('beforeend',`<option value="${esc(chosen)}">${esc(chosen)} (niet in lijst)</option>`);sel.value=chosen||''}function previewValue(){let e=entities.find(x=>x.entity_id===sel.value);let raw=attr.value?e?.attributes?.[attr.value]:e?.state;let valid=e&&!['unknown','unavailable','none',''].includes(String(e.state??'').toLowerCase())&&raw!=null;r.querySelector('.live').textContent=e?tr('Actueel: ','Current: ')+(valid?String(raw)+(attr.value?' '+unit.value:e.unit?' '+e.unit:''):tr('Niet beschikbaar','Unavailable')):''}function show(chosenAttr,auto){let e=entities.find(x=>x.entity_id===sel.value);let attrs=Object.keys(e?.attributes||{});if(chosenAttr&&!attrs.includes(chosenAttr))attrs.push(chosenAttr);attr.innerHTML='<option value="">State</option>'+attrs.map(a=>`<option value="${esc(a)}">${esc(a)}</option>`).join('');attr.value=chosenAttr||'';if(auto&&e){let raw=e.unit;if(sel.value.startsWith('climate.')&&(k==='inside'||k==='target')){attr.value=k==='inside'?'current_temperature':'temperature';raw='°C'}let match=def.units.find(u=>normalize(u)===normalize(raw));if(match)unit.value=match;}previewValue();if(auto&&e&&e.unit&&!attr.value&&def.unit!=='on/off'&&!def.units.some(u=>normalize(u)===normalize(e.unit)))r.querySelector('.live').textContent+=tr(' · controleer eenheid!',' · check unit!')}list(m.entity);unit.value=m.unit||def.units[0];if(on)on.value=m.on_value||'on';show(m.attribute,false);filter.addEventListener('input',()=>list(sel.value));sel.addEventListener('change',()=>show('',true));attr.addEventListener('change',previewValue);unit.addEventListener('change',previewValue);return r}
function renderMapping(){['basic','expert'].forEach(mode=>{let tbody=$(mode+'Mapping');tbody.replaceChildren(...Object.keys(roles).filter(k=>roles[k].mode===mode).map(mappingRow))})}
function readMapping(){let m={};document.querySelectorAll('tr[data-role]').forEach(r=>{let id=r.querySelector('.entity').value;if(id)m[r.dataset.role]={entity:id,attribute:r.querySelector('.attribute').value,unit:r.querySelector('.unit').value,on_value:r.querySelector('.onValue')?.value||'on'}});return m}
async function loadEntities(){try{cfg.mapping=readMapping();$('loadEntities').disabled=true;entities=await api('entities');$('entityStatus').textContent=`${entities.length} beschikbare HA-entiteiten. Filter per meetgrootheid op naam of ID.`;renderMapping()}catch(e){msg('Entiteiten ophalen: '+e.message,true)}finally{$('loadEntities').disabled=false}}
function suggestFlow(k,profile){if(profile==='manual')return;let r=document.querySelector('tr[data-role="'+k+'"]');if(!r)return;let q=r.querySelector('.search');let hints={aquaro:'aquaro',esphome:'pulse_meter',electropaultje:'pulse_meter',openquatt:'flow',generic_mqtt:'flow',modbus_mbus:'flow'};q.value=hints[profile]||'';q.dispatchEvent(new Event('input'));msg('Filter toegepast; kies en controleer zelf de juiste entiteit en eenheid.');}
function populate(){ $('language').value=cfg.language;$('modelProfile').value=cfg.model;$('integrationProfile').value=cfg.integration_profile;$('entityPrefix').value=cfg.entity_prefix; $('flowProfile').value=cfg.flow_profile||'manual';$('referenceFlowProfile').value=cfg.reference_flow_profile||'manual'; $('heatOnly').value=String(cfg.heat_only);$('buhMode').value=cfg.buh_mode;$('buhThermal').value=cfg.buh_thermal;$('maxHz').value=cfg.max_hz;$('hzThreshold').value=cfg.hz_threshold;$('waterFactor').value=cfg.water_factor;$('backfill').value=cfg.backfill_days;$('poll').value=cfg.poll_seconds;$('counterGap').value=cfg.counter_max_gap;$('regional').checked=cfg.regional.enabled;$('lat').value=cfg.regional.latitude??'';$('lon').value=cfg.regional.longitude??'';$('notes').value=cfg.notes;renderMapping()}
async function save(){let m=readMapping();let rr={enabled:$('regional').checked,latitude:$('lat').value,longitude:$('lon').value};let next={...cfg,mapping:m,model:$('modelProfile').value,integration_profile:$('integrationProfile').value,entity_prefix:$('entityPrefix').value,flow_profile:$('flowProfile').value,reference_flow_profile:$('referenceFlowProfile').value,heat_only:$('heatOnly').value==='true',buh_mode:$('buhMode').value,buh_thermal:$('buhThermal').value,max_hz:$('maxHz').value,hz_threshold:$('hzThreshold').value,water_factor:$('waterFactor').value,backfill_days:$('backfill').value,poll_seconds:$('poll').value,counter_max_gap:$('counterGap').value,regional:rr,notes:$('notes').value};let missing=['inside','outside','supply','return','power'].filter(k=>!m[k]&&!(k==='outside'&&rr.enabled));if(!m.flow&&!m.flow_counter)missing.push('flow');let warn=missing.length?['Nog niet gekoppeld: '+missing.map(k=>labels[k]).join(', ')]:[];if(!next.heat_only&&!m.heating)warn.push('Map de status ruimteverwarming of bevestig uitsluitend verwarmen.');if(next.buh_mode==='separate'&&!m.buh)warn.push('Koppel BUH-vermogen.');$('mappingWarnings').innerHTML=warn.map(x=>`<div>${esc(x)}</div>`).join('');if(rr.enabled&&(!rr.latitude||!rr.longitude)){msg('Vul geldige coördinaten in.',true);return}try{await api('config',next);cfg=(await api('config')).config;msg('Configuratie opgeslagen. Historie wordt in batches opgehaald.');await health()}catch(e){msg(e.message,true)}}
let preview=null;
async function preset(){preview=null;$('applyProfile').disabled=true;$('applyBoundary').hidden=true;$('profilePreview').textContent='';try{let profile=$('integrationProfile').value;if(profile==='manual')throw new Error('Choose an integration profile first.');preview=await api('profile-preview',{profile,prefix:$('entityPrefix').value,model:$('modelProfile').value,existing:readMapping()});$('profilePreview').innerHTML='<p><a target="_blank" rel="noopener" href="'+esc(preview.source)+'">Source / Bron</a></p><p>'+esc(preview.power_note)+'</p><table><thead><tr><th>Role / Meetgrootheid</th><th>Candidate / Entiteit</th><th>Status</th></tr></thead><tbody>'+preview.rows.map((r,i)=>'<tr><td>'+esc(labels[r.role]||r.role)+'</td><td>'+esc(r.candidates[0]?.entity||r.suffix)+'</td><td>'+(r.status==='ready'?'<label><input type="checkbox" data-profile-row="'+i+'" checked> ready</label>':esc(r.status)+(r.disabled_default?' · Check HA: disabled by default':'') )+'</td></tr>').join('')+'</tbody></table><p>Missing? HA → Settings → Devices & services → Entities. Enable relevant sensors and check Recorder.</p>';$('applyProfile').disabled=false;$('applyBoundary').hidden=!preview.boundary_hint;$('boundaryHint').textContent=preview.boundary_hint?'Amber: verify Tuo/Tui measure across the internal heater using the installation diagram. Electrical BUH metering remains manual.':'';}catch(e){msg(e.message,true)}}
