$('sizingPanel').hidden=true;modelData=null;$('modelBtn').disabled=true;$('modelOutput').textContent=tr('Berekenen…','Calculating…');
let p=$('modelPeriod').value,r=await api('model'+(p==='dashboard'?query():'?hours='+p));
let reasons={partial_hour:tr('Onvolledig uur','Partial hour'),thermal_or_boundary_coverage:tr('Onvoldoende warmte-/COP-dekking of onbekende meetgrens','Insufficient heat/COP coverage or unknown boundary'),temperature_coverage:tr('Onvoldoende binnen-/buitentemperatuurdata','Insufficient indoor/outdoor data'),small_delta_t:tr('Binnen-buitenverschil kleiner dan 5 K','Indoor-outdoor difference below 5 K'),no_adjacent_hour:tr('Geen aansluitend geschikt vorig uur','No preceding eligible adjacent hour'),indoor_temperature_change:tr('Binnentemperatuur verandert meer dan 0,15 °C tussen uurgemiddelden','Indoor temperature changes over 0.15 °C between hourly means'),other_heat_coverage:tr('Onvoldoende dekking andere warmtebron','Insufficient other heat source coverage')};
