if(r.status==='exploratory')result+='<div class="cards">'+card(tr('Geschatte warmteverliescoëfficiënt','Estimated heat-loss coefficient'),fmt(r.heat_loss_w_per_k),'W/K')+card('R²',fmt(r.r2))+card('RMSE',fmt(r.rmse_kw),'kW')+'</div><p>'+esc(tr('Temperatuurverschilbereik: ','Temperature difference range: ')+r.delta_t_range_c.map(v=>fmt(v)).join(' – ')+' K')+'</p>';
