async function compare(){try{let a=['beforeStart','beforeEnd','afterStart','afterEnd'];if(a.some(k=>!$(k).value))throw new Error('Kies alle vier tijdstippen.');let q=new URLSearchParams(Object.fromEntries(a.map(k=>[k.replace(/[A-Z]/g,c=>'_'+c.toLowerCase()),$(k).value])));let r=await api('compare?'+q);let keys=['net_thermal_kw','net_thermal_kwh','system_electrical_kwh','system_cop','cop_coverage_pct','thermal_coverage_pct','defrost_minutes','defrost_pct_observed','compressor_high_pct_observed','comfort_deficit_degree_hours','comfort_mean_deficit_c','comfort_max_deficit_c','comfort_excess_degree_hours','comfort_within_band_pct','comfort_coverage_pct','buh_kwh'];let rows=[...keys.map(k=>[k,r.before[k],r.after[k]]),...['inside','outside','humidity','wind','solar'].map(k=>[labels[k],r.before.means[k],r.after.means[k]])];$('comparison').innerHTML=`<table><thead><tr><th>Indicator</th><th>Voor (${fmt(r.before.hours,1)} uur)</th><th>Na (${fmt(r.after.hours,1)} uur)</th></tr></thead><tbody>${rows.map(([k,v,w])=>`<tr><td>${esc(k)}</td><td>${fmt(v)}</td><td>${fmt(w)}</td></tr>`).join('')}</tbody></table><p class="hint">${esc(r.warning)}</p>`}catch(e){msg(e.message,true)}}
